package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.net.TrafficStats;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.util.*;
/** Six keypad categories, inspired by the local KaiOS settings reference. */
public final class SettingsActivity extends LeoActivity {
    static final String[] TABS=L.array(new String[]{"Rețele","Aspect","Sunet","Siguranță","Stocare","Telefon"});
    private static final String[][] ROWS=L.array(new String[][]{{"Wi-Fi","Bluetooth","Hotspot Wi-Fi","SIM-uri și rețea mobilă","Transfer USB","Trafic de date","Panou conexiuni Leo"},{"Ecran și taste","Fundaluri și teme","Personalizare","Tastatură și text"},{"Sunete și tonuri","Volume separate","Profiluri sonore","Notificări"},{"Blocarea tastelor","Permisiuni și aplicații","Localizare","Accesibilitate Leo"},{"Spațiu telefon / card SD","Fișiere Leo","Descărcări Leo","Backup Leo"},{"Baterie","Dată și oră","Diagnostic Leo","Despre telefon","Setări Android","Configurare inițială","Ajutor Leo","Actualizări Leo","Leo Studio"}});
    private int[] selections=new int[TABS.length];private int category;private boolean categories;
    protected void onCreate(Bundle state){super.onCreate(state);category=Math.max(0,Math.min(TABS.length-1,state==null?getSharedPreferences("settings-ui",0).getInt("category",0):state.getInt("category",0)));if(state!=null&&state.getIntArray("selections")!=null&&state.getIntArray("selections").length==TABS.length)selections=state.getIntArray("selections");}
    protected void onResume(){super.onResume();show();}
    protected void onPause(){getSharedPreferences("settings-ui",0).edit().putInt("category",category).apply();super.onPause();}
    protected void onSaveInstanceState(Bundle b){b.putInt("category",category);b.putIntArray("selections",selections);super.onSaveInstanceState(b);}
    private void show(){categories=true;final int current=category;list(L.t("Setări Leo · ")+(category+1)+" / "+TABS.length,Arrays.asList(ROWS[category]),selections[category],new Choice(){public void pick(int i){selections[current]=i;open(current,i);}},L.t("Categorii"),new Runnable(){public void run(){options(L.t("Categorii"),TABS,new Choice(){public void pick(int i){switchCategory(i);}});}});LinearLayout tabs=KeypadTabs.create(this,new String[]{TABS[KeypadTabs.next(category,-1,TABS.length)],TABS[category],TABS[KeypadTabs.next(category,1,TABS.length)]},1,new Choice(){public void pick(int offset){switchCategory(current+offset-1);}},new Runnable(){public void run(){KeypadTabs.focusList(SettingsActivity.this);}});root.addView(tabs,1);}
    private void switchCategory(int next){category=KeypadTabs.next(next,0,TABS.length);show();}
    void onListSelection(String title,int index){if(categories&&title.startsWith(L.t("Setări Leo")))selections[category]=index;}
    android.graphics.drawable.Drawable rowIcon(String title,int index){return title.startsWith(L.t("Setări Leo"))&&index<ROWS[category].length?new AppBadge(ROWS[category][index],dp(27)):null;}
    private void start(Class<?> type){startActivity(new Intent(this,type));}
    private void open(int group,int row){if(group==0){if(row==6){start(ConnectionDashboardActivity.class);return;}if(row<3)startActivity(new Intent(this,ConnectivityActivity.class).putExtra("kind",new String[]{"wifi","bluetooth","hotspot"}[row]));else if(row==3)start(MobileSettingsActivity.class);else if(row==4)start(UsbTransferActivity.class);else traffic();}else if(group==1){start(new Class<?>[]{DisplaySettingsActivity.class,WallpaperActivity.class,PersonalizationActivity.class,InputSettingsActivity.class}[row]);}else if(group==2){if(row==0)start(SoundSettingsActivity.class);else if(row==1)startActivity(new Intent(this,QuickSettingsActivity.class).putExtra("volumes",true));else if(row==2)SoundProfiles.select(this,new Runnable(){public void run(){show();}});else start(NotificationSettingsActivity.class);}else if(group==3){start(new Class<?>[]{KeypadLockSettingsActivity.class,AppControlActivity.class,PrivacySettingsActivity.class,AccessibilitySettingsActivity.class}[row]);}else if(group==4){start(new Class<?>[]{StorageSettingsActivity.class,FilesActivity.class,DownloadsActivity.class,BackupActivity.class}[row]);}else if(row==0)start(BatterySettingsActivity.class);else if(row==1)start(DateTimeSettingsActivity.class);else if(row==2)start(DiagnosticActivity.class);else if(row==3)page(L.t("Despre Leo"),Build.MODEL+"\nAndroid "+Build.VERSION.RELEASE+" · API "+Build.VERSION.SDK_INT+L.t("\nShell nativ pentru taste\n")+Build.DISPLAY);else if(row==4){try{startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(RuntimeException e){notice(L.t("Setări Android indisponibile"));}}else if(row==8)start(PremiumStudioActivity.class);else if(row==7)start(UpdatesActivity.class);else if(row==6)start(HelpActivity.class);else start(SetupWizardActivity.class);}
    private String bytes(long value){return value<0?L.t("Neraportat"):android.text.format.Formatter.formatFileSize(this,value);}
    private void traffic(){page(L.t("Trafic de date"),L.t("De la pornire / contoarele interfețelor\n\nMobil primit · ")+bytes(TrafficStats.getMobileRxBytes())+L.t("\nMobil trimis · ")+bytes(TrafficStats.getMobileTxBytes())+L.t("\nTotal primit · ")+bytes(TrafficStats.getTotalRxBytes())+L.t("\nTotal trimis · ")+bytes(TrafficStats.getTotalTxBytes())+L.t("\n\nNu este contorul facturii operatorului și nu reprezintă un ciclu lunar."));}
    private void page(String title,String value){categories=false;begin(title);ScrollView scroll=new ScrollView(this);scroll.addView(text(value,17));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setFocusable(true);scroll.requestFocus();back=new Runnable(){public void run(){show();}};footer("",L.t("Derulează"),L.t("Înapoi"));}
    public boolean dispatchKeyEvent(KeyEvent event){if(categories&&(event.getKeyCode()==KeyEvent.KEYCODE_DPAD_LEFT||event.getKeyCode()==KeyEvent.KEYCODE_DPAD_RIGHT)){if(event.getAction()==0&&event.getRepeatCount()==0)switchCategory(category+(event.getKeyCode()==KeyEvent.KEYCODE_DPAD_RIGHT?1:-1));return true;}return super.dispatchKeyEvent(event);}
}
